            return;
        const resizeObserver = new ResizeObserver(() => {
            cancelAnimationFrame(rAF);
            rAF = window.requestAnimationFrame(onResize);
        });
        resizeObserver.observe(_node);
        return () => {
            window.cancelAnimationFrame(rAF);
            resizeObserver.unobserve(_node);
        };
    });
}
